for (const [locale, labels] of Object.entries(UI_TEXT_PLATFORM_USAGE)) {
  Object.assign(UI_TEXT_PLATFORM_MODELS[locale], labels);
}

export function normalizeUiLanguage(value) {
  return UI_LANGUAGE_OPTIONS.some((option) => option.value === value) ? value : 'zh-CN';
}

export function getUiText(language, key, fallback = key) {
  const locale = normalizeUiLanguage(language);
  if (locale === 'zh-CN' || locale === 'en-US') return UI_TEXT_PLATFORM_MODELS[locale]?.[key] || UI_TEXT_ADMIN_SYSTEM[locale]?.[key] || UI_TEXT_DISCUSSION_PAGINATION[locale]?.[key] || UI_TEXT_ORDER_FEEDBACK[locale]?.[key] || UI_TEXT_OPERATIONS_BACKUP[locale]?.[key] || UI_TEXT_EXPORT_WORD[locale]?.[key] || UI_TEXT_PRO_FEATURES[locale]?.[key] || UI_TEXT[locale][key] || fallback;
  return UI_TEXT_PLATFORM_MODELS[locale]?.[key] || UI_TEXT_ADMIN_SYSTEM[locale]?.[key] || UI_TEXT_DISCUSSION_PAGINATION[locale]?.[key] || UI_TEXT_ORDER_FEEDBACK[locale]?.[key] || UI_TEXT_OPERATIONS_BACKUP[locale]?.[key] || UI_TEXT_EXPORT_WORD[locale]?.[key] || UI_TEXT_PRO_FEATURES[locale]?.[key] || UI_TEXT_DISCUSSION_MODERATION[locale]?.[key] || UI_TEXT_LOCALIZED[locale]?.[key] || UI_TEXT_HOME_FORM_LOCALIZED[locale]?.[key] || UI_TEXT_PLATFORM_MODELS['en-US'][key] || UI_TEXT_ADMIN_SYSTEM['en-US'][key] || UI_TEXT_DISCUSSION_PAGINATION['en-US'][key] || UI_TEXT_ORDER_FEEDBACK['en-US'][key] || UI_TEXT_OPERATIONS_BACKUP['en-US'][key] || UI_TEXT_EXPORT_WORD['en-US'][key] || UI_TEXT_PRO_FEATURES['en-US'][key] || UI_TEXT['en-US'][key] || fallback;
}

export function formatUiText(template, values = {}) {
  return String(template).replace(/\{(\w+)\}/g, (_, key) => String(values[key] ?? `{${key}}`));
}
